export const json = (v) => `${JSON.stringify(v, null, 2)}\n`;
const rows = (home, sql, ...params) => withStore(home, (db) => db.prepare(sql).all(...params));
const one = (home, sql, ...params) => withStore(home, (db) => db.prepare(sql).get(...params));
const parse = (v) => (v === null || v === undefined ? v : typeof v === 'string' ? JSON.parse(v) : v);
const clone = (v) => structuredClone(v);

export const MIB = 1024 * 1024;
// D7 A.7 (SEAM.md §§516, 522): per file and per review.
export const EVIDENCE_FILE_DEFAULT = 64 * MIB;
export const EVIDENCE_REVIEW_DEFAULT = 512 * MIB;
export const EVIDENCE_REVIEW_KEY = 'design_review_evidence_max_review_bytes';
export const EVIDENCE_FILE_KEY = 'design_review_evidence_max_bytes';

// ---- evidence bytes with valid headers (rule 22; nothing decoded) --------------------------------

// A JPEG: SOI, a JFIF APP0 segment, EOI; `pad` bytes of a COM segment's text.
export function jpegOf({ pad = 0 } = {}) {
  const app0 = Buffer.from([0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46, 0x49, 0x46, 0x00, 0x01, 0x01, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00]);
  const com = [];
  for (let left = pad; left > 0; ) {
    const n = Math.min(left, 65533);
    const len = Buffer.alloc(2);
    len.writeUInt16BE(n + 2);
    com.push(Buffer.from([0xff, 0xfe]), len, Buffer.alloc(n, 0x61));
    left -= n;
  }
  return Buffer.concat([Buffer.from([0xff, 0xd8]), app0, ...com, Buffer.from([0xff, 0xd9])]);
}
// An MP4: an `ftyp` box (isom) and an empty `mdat`; `pad` bytes inside a `free` box.
export function mp4Of({ pad = 0 } = {}) {
  const box = (type, data) => {
    const head = Buffer.alloc(8);
    head.writeUInt32BE(8 + data.length);
    head.write(type, 4, 'ascii');
    return Buffer.concat([head, data]);
  };
  const ftyp = box('ftyp', Buffer.concat([Buffer.from('isom', 'ascii'), Buffer.from([0, 0, 2, 0]), Buffer.from('isommp41', 'ascii')]));
  return Buffer.concat([ftyp, ...(pad > 0 ? [box('free', Buffer.alloc(pad))] : []), box('mdat', Buffer.alloc(0))]);
}
// A WebM: an EBML header whose DocType is `webm`; `pad` bytes after it.
export function webmOf({ pad = 0 } = {}) {
  const body = Buffer.from([0x42, 0x86, 0x81, 0x01, 0x42, 0xf7, 0x81, 0x01, 0x42, 0x82, 0x84, 0x77, 0x65, 0x62, 0x6d, 0x42, 0x87, 0x81, 0x02, 0x42, 0x85, 0x81, 0x02]);
  return Buffer.concat([Buffer.from([0x1a, 0x45, 0xdf, 0xa3, 0x80 | body.length]), body, Buffer.alloc(pad)]);
}
// One file of each format by its extension, each distinct (`tag` varies the bytes).
export const EVIDENCE_FORMATS = Object.freeze(['png', 'webp', 'jpeg', 'mp4', 'webm']);
export function evidenceBytes(format, { tag = 0, pad = 0 } = {}) {
  if (format === 'png') return flatPng(4 + tag, 4, { pad });
  if (format === 'webp') return webpOf(16 + tag, 16, { pad });
  if (format === 'jpeg') return jpegOf({ pad: pad + tag + 1 });
  if (format === 'mp4') return mp4Of({ pad: pad + tag + 1 });
  if (format === 'webm') return webmOf({ pad: pad + tag + 1 });
  throw new Error(`no evidence format ${format}`);
}
const EXTENSION = Object.freeze({ png: 'png', webp: 'webp', jpeg: 'jpg', mp4: 'mp4', webm: 'webm' });
export const extensionOf = (format) => EXTENSION[format];

// Files written under the test's root, in a directory of their own: {name: bytes} → [absolute paths].
export function evidenceFiles(fx, files) {
  fx.evidenceDirs = (fx.evidenceDirs ?? 0) + 1;
  const dir = join(fx.root, `evidence-${fx.evidenceDirs}`);
  mkdirSync(dir, { recursive: true });
  return Object.entries(files).map(([name, bytes]) => {
    const path = join(dir, name);
    writeFileSync(path, bytes);
    return path;
  });
}

// ---- the owner's review commands (D7 §10.5, A.8; SEAM.md §§502, 522) ----------------------------

// `surety design review --project <p> --target <t> --build <id> [--candidate <c>]
// [--observed-on <o>] [--evidence <file>…]`: {status, body, stdout, stderr}.
export function designReview(fx, project, { target, build, candidate, observedOn, evidence = [] }) {
  const args = ['design', 'review', '--project', project, '--target', target, '--build', build];
  if (candidate) args.push('--candidate', candidate);
  if (observedOn) args.push('--observed-on', observedOn);
  if (evidence.length > 0) args.push('--evidence', ...evidence);
  return cli(fx, args);
}
// `POST …/design/reviews {target, build_ref, candidate?}` (SEAM.md §502), the raw response.
export const postReview = (fx, project, body) => fx.engine.post(`/v1/projects/${project}/design/reviews`, body);

// `surety design verdicts --project <p> <review> confirm|reject [--edit <json>]…
// [--strike <target>/<screen>]… [--severity <s>]`: {status, body, stdout, stderr}.
export function designVerdicts(fx, project, review, option, { edits = [], strikes = [], severity } = {}) {
  const args = ['design', 'verdicts', '--project', project, review, option];
  for (const e of edits) args.push('--edit', JSON.stringify(e));
  for (const s of strikes) args.push('--strike', `${s.target}/${s.screen}`);
  if (severity) args.push('--severity', severity);
  return cli(fx, args);
}

// A review file (B.14) as text.
export const reviewJson = ({ design_version = 1, subject, screens, revised_design = false, first_design = false }) =>
  json({ ...(design_version === null ? {} : { design_version }), subject, screens, revised_design, first_design });
export const REVIEW_FILE = (n = 1) => `${DESIGN_DIR}reviews/review-${n}.json`;

// One review-mode session's turns: each {files?, say?, dump?, steps?, done?};
// a save after each turn whose `save` is not false; closed with `close`
// (null leaves it open). `run` the session's run (opened by the caller).
// Returns {turns, saves, close}.
export async function driveReview(fx, project, run, turns, { close = {} } = {}) {
  // A session already driven keeps its earlier launches' scripts in place (as check41.mjs's checkSession).
  const earlier = fx.scripted.launches({ run: run.id }).length;
  const talk = { steps: [step.result(turnResult({ reply: 'Read the engine\'s notes.' }))] };
  scriptTurns(
    fx,
    run.id,
    [...Array.from({ length: earlier }, () => talk), ...turns.map((t) => ({
      steps: [
        ...(t.dump ? [step.probe('context_dump')] : []),
        ...(t.steps ?? []),
        ...(t.clear ? [step.delete(`${DESIGN_DIR}mockups`)] : []),
        ...Object.entries(t.files ?? {}).map(([path, content]) => (Buffer.isBuffer(content) ? step.writeBytes(path, content) : step.write(path, content))),
        step.result(turnResult({ reply: t.reply ?? 'The review is written.', artifact_changed: Object.keys(t.files ?? {}).length > 0, ...(t.done ? { done: true } : {}) })),
      ],
    }))],
  );
  const out = { turns: [], saves: [], close: null };
  for (const t of turns) {
    out.turns.push(await sayAndSettle(fx, project, run.id, t.say ?? 'Review it with me.'));
    out.saves.push(t.save === false ? null : await postSaveRaw(fx, project, run.id));
  }
  if (close !== null) out.close = await postCloseRaw(fx, project, run.id, close);
  return out;
}

// ---- reads (D7 A.3; SEAM.md §§523, 524) ---------------------------------------------------------

// Every review of the project by insertion (`design_reviews.project` †).
export const reviewsOf = (home, project) =>
  rows(home, 'SELECT * FROM "design_reviews" WHERE "project" = ? ORDER BY rowid', project).map((r) => ({ ...r, subject: parse(r.subject), verdicts: parse(r.verdicts) ?? [], findings: parse(r.findings) ?? [] }));
export const reviewRow = (home, id) => {
  const r = one(home, 'SELECT * FROM "design_reviews" WHERE "id" = ?', id);
  return r ? { ...r, subject: parse(r.subject), verdicts: parse(r.verdicts) ?? [], findings: parse(r.findings) ?? [] } : null;
};
export const evidenceRow = (home, id) => one(home, 'SELECT * FROM "design_evidence" WHERE "id" = ?', id) ?? null;
export const evidenceOfReview = (home, review) => rows(home, 'SELECT * FROM "design_evidence" WHERE "review" = ? ORDER BY rowid', review);
export const countOf = (home, table, where = '1 = 1', ...params) => one(home, `SELECT COUNT(*) AS n FROM "${table}" WHERE ${where}`, ...params)?.n ?? 0;
export const findingsOf = (home, project) => rows(home, 'SELECT * FROM "findings" WHERE "project" = ? ORDER BY "seq"', project);
export const designerRuns = (home, project) => rows(home, 'SELECT * FROM "runs" WHERE "project" = ? AND "role" = \'designer\' ORDER BY "seq"', project);
export const verdictOf = (review, target, screen) => (review?.verdicts ?? []).find((v) => v.target === target && (v.screen ?? v.key) === screen) ?? null;
export const reviewEvents = (home, type, project) => eventsOfType(home, type).filter((e) => e.subject?.project === project);

// The open design_verdicts about a review (its subject), or the newest open one.
export const openVerdicts = (home, project, review) =>
  decisionsOfKind(home, project, 'design_verdicts').filter((d) => d.status === 'open' && (review === undefined || d.subject_id === review)).at(-1) ?? null;
// The members of a decision's batch by kind (open ones).
export function batchMembers(home, project, batchKey) {
  if (!batchKey) return {};
  return Object.fromEntries(rows(home, 'SELECT "id", "kind" FROM "decisions" WHERE "project" = ? AND "batch_key" = ? AND "status" = \'open\'', project, batchKey).map((r) => [r.kind, decision(home, r.id)]));
}
export const blockersOf = (row, option = 'approve') => (row?.options ?? []).find((o) => o.key === option)?.blockers ?? [];

// GET …/design (SEAM.md §480) and its human test of a target.
export async function readDesign(fx, project) {
  const res = await fx.engine.get(`/v1/projects/${project}/design`);
  assert.equal(res.status, 200, `GET …/design (→ ${res.status} ${res.text?.slice(0, 400)})`);
  return res.body;
}
export const humanTestOf = (design, target) => (design?.human_tests ?? []).find((h) => h.target === target) ?? null;
export const reviewInDesign = (design, id) => (design?.reviews ?? []).find((r) => r.id === id) ?? null;

// The package a session's launch dumped: {name: {sha256, text, size}}.
export function packageOfLaunch(fx, run, index = 0) {
  const launch = fx.scripted.launches({ run })[index];
  if (!launch) return null;
  const dump = fx.scripted.probes(launch.invocation, 'context_dump').at(-1);
  if (!dump || dump.outcome !== 'dumped') return null;
  return Object.fromEntries((dump.files ?? []).filter((f) => f.type === 'file').map((f) => [f.name, { sha256: f.sha256 ?? null, text: f.text ?? null, size: f.size }]));
}
export const packageJson = (pkg, name) => {
  const f = pkg?.[name];
  if (!f || f.text === null || f.text === undefined) return null;
  return JSON.parse(f.text);
};

// ---- M517's design criterion and its check (D7 §7.2; SEAM.md §518) -----------------------------

export const MARKER = 'marker-android';
const WRAPPER_PATH = '.surety/checks/wrapper.mjs';
const MARKER_TEST = '.surety/checks/tests/marker-android.test.mjs';
export const R3_2 = 'Given the mobile module, when mobile/App.js is read, then each row of the list carries the accessibility label "pantry-item".';
export const MARKER_CRITERION = Object.freeze({ requirement: 'R3', text: R3_2, kind: 'state_marker_present', targets: ['android'], paths: ['mobile/App.js'] });
export const MARKER_CORRECTION = roleThat(
  [
    step.write(MARKER_TEST, `import assert from 'node:assert/strict';\nimport { readFileSync } from 'node:fs';\nimport { test } from 'node:test';\n\ntest('R3.2: the rows carry the label', () => {\n  assert.match(readFileSync('mobile/App.js', 'utf8'), /accessibilityLabel="pantry-item"/);\n});\n`),
    step.write('.surety/checks/defs/marker-android.json', definitionText(MARKER, { inputs: [WRAPPER_PATH, MARKER_TEST], kind: 'acceptance', command: ['node', WRAPPER_PATH, MARKER_TEST], timeout_s: 120, gate_kinds: ['stage', 'alpha_authorize'], covers: { criteria: ['R3.2'] } })),
  ],
  { proposal: { rationale: 'The approved design added R3.2: its check.', requested_change_kind: 'tightening' } },
);
// The marker check failing (1) on the candidates of `old` (every candidate when `old` is null), passing elsewhere.
export const markerFails = (old = null) => (x) => (x.key === MARKER && (old === null || old.has(x.candidate)) ? 1 : 0);
export const markerPasses = () => () => 0;

// The delivery stage and replan of M517 (D7 §10.4; E153 item 1): R3 moved into a delivery phase 2.
const DELIVERY_STAGE = Object.freeze({ number: 4, goal: 'deliver the design change to R3', tasks: ['label each row of the Android list'], modules: ['mobile'], implements: ['R3'], adrs: [ADR_KEY], depends_on: [], validation: { criteria: ['R3.1', 'R3.2'], kinds: T2_KINDS, sensitive_areas: [] }, integration_obligations: [] });
export function deliveryReplan(fx, project, { spec_version = 2 } = {}) {
  const roadmap = roadmapRevision(fx.home, project, (phases) => [
    ...phases.map((p) => (p.number === 1 ? { ...p, requirement_ids: p.requirement_ids.filter((k) => k !== 'R3') } : p)),
    { number: 2, goal: 'deliver the approved design change to R3', modules: ['mobile'], requirement_ids: ['R3'], depends_on: [] },
  ], { moved: [{ key: 'R3', from: 1, to: 2 }] });
  return replanWith({ phase: 2, stages: [DELIVERY_STAGE], spec_version, roadmap_version: currentRoadmap(fx.home, project).version, roadmap });
}
export const DELIVERY_BUILDER = roleThat([step.write('mobile/App.js', APP_JS.replace('return null;', 'return null; // accessibilityLabel="pantry-item"'))]);

// ---- Pantry at Alpha with no design approved (M529; D7 §10.6) -----------------------------------

export const TO_ALPHA = Object.freeze({ autonomy: 'phase', alpha_deploy: 'on_phase_complete', phase_size: { min: 1, max: 5 } });

// Pantry under `at_alpha` (or `both` with the design before build waived by
// the owner's `design_due` answer), built with no design and
// `alpha_deployed` on the kernel lane; the `alpha_review` design_due awaited.
// Returns {p, ctx, deployed, due, waived?}.
export async function toAlphaWithoutDesign(fx, { name, waive = false, exits = () => 0 } = {}) {
  const policy = { ...TO_ALPHA, design: waive ? 'both' : 'at_alpha' };
  const { p } = await toPublished(fx, { policy, name });
  designScripts(fx);
  scriptBuilders(fx, p.id, { noDesign: true });
  const ctx = journeyContext(fx, p, { lane: 'kernel' });
  ctx.answerKinds = [...KERNEL_KINDS];
  let waived = null;
  if (waive) {
    const before = await pump(fx, ctx, () => openDesignDue(fx.home, p.id) ?? undefined, { what: 'design_due raised before build', max: 10 });
    const res = await fx.engine.post(`/v1/projects/${p.id}/decisions/${before.id}/answer`, { option: 'waive', preview_hash: before.preview_hash, note: 'Build it first; I will design it at Alpha.' });
    assert.equal(res.status, 200, `design_due answered waive (${res.text})`);
    waived = before;
  }
  await alphaReady(fx, ctx);
  const deployed = await alphaDeployed(fx, ctx, { max: 200, exits });
  const due = await pump(fx, ctx, () => {
    const d = openDesignDue(fx.home, p.id);
    return d?.evidence?.stage === 'alpha_review' ? d : undefined;
  }, { what: 'design_due (alpha_review) on alpha_complete', max: 20, exits });
  await waitForIdle(fx.home, p.id);
  return { p, ctx, deployed, due, waived };
}

// ---- Pantry with no web target (M528 (g); D7 §10.1) ----------------------------------------------

const ANDROID_REQUIREMENTS = Object.freeze([REQUIREMENTS[0], REQUIREMENTS[2]]);
const ANDROID_MODULES = Object.freeze({
  ...MODULES_JSON,
  modules: [
    { ...MODULES_JSON.modules[0], interfaces: [INTERFACES.list, INTERFACES.add].map((i) => ({ ...i, consumed_by: ['mobile'] })).concat([INTERFACES.health]) },
    { ...MODULES_JSON.modules[2], asset_paths: undefined },
  ].map((m) => Object.fromEntries(Object.entries(m).filter(([, v]) => v !== undefined))),
  mapping_from_spec: [MODULES_JSON.mapping_from_spec[0], MODULES_JSON.mapping_from_spec[2]],
});
const ANDROID_STAGES = Object.freeze([STAGES[0], { ...STAGES[2], number: 2 }]);
const ANDROID_ROADMAP = Object.freeze({ ...ROADMAP_JSON, phases: [{ ...ROADMAP_JSON.phases[0], goal: 'the pantry on Android', modules: ['api', 'mobile'], requirement_ids: ['R1', 'R3'] }] });
// Phase 1's authoring without the web page's checks.
const ANDROID_AUTHORING = () => Object.fromEntries(Object.entries(authoringFiles()).filter(([path]) => !/web\.test\.mjs$|integration-web|accept-r2\.json$/.test(path)));
export const ANDROID_ONLY = Object.freeze({
  spec: specText({ requirements: ANDROID_REQUIREMENTS, targets: '**Targets:** android', crossPlatform: null, modules: [SPEC_MODULES[0], SPEC_MODULES[2]] }),
  files: { modules: ANDROID_MODULES, roadmap: ANDROID_ROADMAP, stages: ANDROID_STAGES },
});
// The android-only Pantry under `at_alpha`, built and `alpha_deployed`; the
// `alpha_review` design_due awaited. Returns {p, ctx, deployed, due}.
export async function androidOnlyAtAlpha(fx, { name = 'pantry-android-only' } = {}) {
  const { p } = await toPublished(fx, { policy: { ...TO_ALPHA, design: 'at_alpha' }, name, spec: ANDROID_ONLY.spec, files: ANDROID_ONLY.files });
  designScripts(fx);
  fx.scripted.kindScript('check_authoring', [0, 1, 2].map(() => roleThat(Object.entries(ANDROID_AUTHORING()).map(([path, text]) => step.write(path, text)), { proposal: { rationale: 'The Verifier authors phase 1\'s checks.', requested_change_kind: 'unclassifiable' } })));
  const builders = { 1: roleThat([step.write('server.mjs', SERVER_MJS)]), 2: roleThat([step.write('mobile/App.js', APP_JS)]) };
  for (const n of [1, 2]) {
    const w = stageWork(fx.home, p.id, n);
    if (w) fx.scripted.script(w.id, [builders[n], builders[n], builders[n]]);
  }
  const ctx = journeyContext(fx, p, { lane: 'kernel' });
  ctx.answerKinds = [...KERNEL_KINDS];
  await alphaReady(fx, ctx);
  const deployed = await alphaDeployed(fx, ctx, { max: 200 });
  const due = await pump(fx, ctx, () => {
    const d = openDesignDue(fx.home, p.id);
    return d?.evidence?.stage === 'alpha_review' ? d : undefined;
  }, { what: 'design_due (alpha_review) on the android-only Alpha', max: 20 });
  return { p, ctx, deployed, due };
}

// ---- the review at Alpha's Pantry (M516; D7 §10.2) ---------------------------------------------

// The synthetic secret (never a real credential): the served page carries it,
// assembled by the server at run time, so no file of the repository holds it.
const SECRET_PARTS = Object.freeze(['m516', 'synthetic', 'b7e4c19a2f05d3']);
export const SERVED_SECRET = SECRET_PARTS.join('-');
export const SECRET_REF = 'design-review-m516';
// The API stage's server: SERVER_MJS with `/` answering index.html and a
// build tag (the secret) placed in its head at run time.
export const REVIEW_SERVER = SERVER_MJS.replace(
  "  if (req.method === 'GET' && url.pathname === '/') return file(res, 'index.html');\n",
  `  if (req.method === 'GET' && url.pathname === '/') {\n    return readFile(new URL('index.html', WEB)).then((b) => {\n      res.writeHead(200, { 'content-type': TYPES.html });\n      res.end(b.toString('utf8').replace('</head>', '<meta name="build" content="' + ${JSON.stringify(SECRET_PARTS)}.join('-') + '">\\n</head>'));\n    }, () => send(res, 404, { error: 'not found' }));\n  }\n`,
);
// A page past adapter_output_max_bytes (its default, 1 MiB): 1.5 MiB.
export const BIG_PAGE_PATH = 'web/big.html';
export const BIG_PAGE = `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><title>Pantry, every item</title></head><body><main id="S3">\n${'<p class="item">rice, 2 pcs</p>\n'.repeat(49152)}</main></body></html>\n`;
// The routes of the review's web screens (B.12 conventions.route).
export const ROUTES = Object.freeze({ S1: '/', S3: '/web/big.html', S4: '/gone' });

// designModel's Pantry with a `tokens_only` criterion on R2 (D7 §7.2, so a
// design check runs on the candidate), and two more web screens, S3 (the
// big page) and S4 (a page the server does not have), each reached by a push
// from S1, each a static mockup of its own.
export const R2_TOKENS = Object.freeze({ requirement: 'R2', text: 'Given the web module, when web/app.css is read, then every colour, size, spacing, radius and duration in it is a custom property defined in web/tokens.css.', kind: 'tokens_only', targets: ['web'], paths: ['web/app.css', 'web/tokens.css'] });
export function reviewModel(inventory) {
  const m = designModel(inventory);
  m.criteria.criteria = [clone(R2_TOKENS)];
  const s1 = screenOf(m, 'S1');
  for (const [key, route, title] of [['S3', ROUTES.S3, 'Pantry, every item'], ['S4', ROUTES.S4, 'Pantry, a page that moved']]) {
    const path = `mockups/web/${key.toLowerCase()}.html`;
    m.screens.screens.push({ ...clone(s1), key, title, flow_steps: ['F1.1'], interfaces: [], states: [], inputs: [], conventions: { ...clone(s1.conventions), route } });
    m.design.mockups.push({ path, kind: 'static_html', screens: [key], external_urls: [] });
    m.mockups[path] = `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><title>${key} ${title}</title><link rel="stylesheet" href="../../tokens.css"></head><body><main><h1>${title}</h1></main></body></html>\n`;
    m.navigation.targets.find((t) => t.target === 'web').edges.push({ from: 'S1', to: key, trigger: `open ${title}`, kind: 'push' });
  }
  const web = m.criteria.human_tests.find((h) => h.target === 'web');
  const conventions = [...new Set(web.not_checkable_yet.map((x) => x.convention))];
  web.screens = ['S1', 'S3', 'S4'];
  web.not_checkable_yet = web.screens.flatMap((screen) => conventions.map((convention) => ({ screen, convention })));
  return m;
}
// The revised design a review writes with a design delta on S4: version 2,
// S4's note, the human tests' texts revised (D7 §10.2: "a revised design in the same tree").
export function revisedReviewModel(model) {
  return variantOf(model, (m) => {
    m.design.version = 2;
    screenOf(m, 'S4').notes = 'Say that the page is not there and link back to the list.';
    m.criteria.human_tests = m.criteria.human_tests.map((h) => ({ ...h, text: `${h.text.replace(/version \d+/, 'version 2')} Revised at Alpha.` }));
  });
}
// The check correction of R2.2 alone (reference.mjs's tokens check and its definition).
export const TOKENS_CORRECTION = roleThat(
  Object.entries(CORRECTION_FILES)
    .filter(([path]) => /tokens\.test\.mjs$|accept-r2-tokens\.json$/.test(path))
    .map(([path, text]) => step.write(path, text)),
  { proposal: { rationale: 'The approved design added R2.2: its check.', requested_change_kind: 'tightening' } },
);
// The stage Builders of the review's Pantry: the API writes REVIEW_SERVER;
// the web Builder places tokens.css and the effective logo from its package,
// writes its page, stylesheet and the big page, and binds the logo; the
// Android Builder as the journey's.
export function reviewBuilders(fx, project) {
  const scripts = {
    1: roleThat([step.write('server.mjs', REVIEW_SERVER)]),
    2: roleThat([step.copyContext(PACKAGE_TOKENS_CSS, 'web/tokens.css'), step.copyContext(PACKAGE_LOGO, WEB_LOGO_PATH), step.write('web/index.html', INDEX_HTML), step.write('web/app.css', APP_CSS), step.write(BIG_PAGE_PATH, BIG_PAGE)], { asset_bindings: [bindingOf('web', WEB_LOGO_PATH)] }),
  };
  for (const n of [1, 2]) {
    const w = stageWork(fx.home, project, n);
    assert.ok(w, `stage ${n}'s build work exists`);
    fx.scripted.script(w.id, [scripts[n], scripts[n], scripts[n]]);
  }
  scriptBuilders(fx, project, { numbers: [3] });
}

// The candidate the review is about and its newest deploy operation.
export const newestCandidate = (home, project) => candidatesOfProject(home, project).at(-1) ?? null;
export const deployOperations = (home, project) => rows(home, 'SELECT * FROM "operations" WHERE "project" = ? AND "kind" = \'deploy\' ORDER BY "seq"', project);

export { ARCHITECTURE_MD, consume, decision };
